  "scope": {
    "include": [
10→      "knowledge/p2-findings через `plan.py add-document` по контракту p2-design#findings-contract",
      "открытые D# через `plan.py add-decision` для продуктовых развилок (без decide)",
      "чтение кода packages/** и фикстур tests/Repo/Arch/Fixtures/** (только чтение)"
    ],
    "exclude": [
      "Правки кода, тестов и фикстур",
      "Принятие решений",
      "Изменение других knowledge-документов"
    ]
