      "required": true,
      "ref": "knowledge/source-review#code-facts"
    },
    {
      "why": "A3/A5/A6/A7/A16/A17/A21/A23 — то, на что опираются P3–P6",
40→      "required": true,
      "ref": "knowledge/source-review#audit-verification"
    },
    {
      "why": "фазы блокировки для scan-baseline",
      "required": true,
      "ref": "knowledge/architecture#invariants"
    },
    {
      "why": "результат и notes type-map (open-пункты)",
50→      "required": true,
      "ref": "P2.2"
    },
    {
      "why": "результат и notes идентичностей (original_diff, расхождения pgsql/mysql)",
      "required": true,
      "ref": "P2.3"
