  "validation": [
100→    {
      "id": "V1",
      "cmd": "PLAN_PY=\"$(ls -d ~/.claude/plugins/cache/swissknifeman/task/*/scripts/plan.py | sort -V | tail -1)\"; for s in code-facts-verification type-map-summary identities-summary scan-baseline open-questions inputs-for-p3-p4; do python3 \"$PLAN_PY\" get 2026.10.13-№1-VAULTER-KERNEL knowledge/p2-findings --section \"$s\" >/dev/null || exit 1; done",
      "expect": "exit 0: все шесть секций существуют",
      "kind": "acceptance"
    },
    {
      "id": "V2",
      "cmd": "scripts/php84 php scripts/inventory/inventory.php --check",
      "expect": "exit 0: фикстуры не изменены",
110→      "kind": "acceptance"
    },
    {
      "id": "V3",
      "cmd": "git diff --quiet 35718fd2 -- packages/*/src packages/*/database packages/*/config packages/*/routes packages/*/composer.json && test -z \"$(git status --porcelain --untracked-files=all -- packages/*/src packages/*/database packages/*/config packages/*/routes)\"",
      "expect": "exit 0: продукт неизменен",
      "kind": "acceptance"
    }
  ],
  "deliverables": [
120→    "knowledge/p2-findings (6 секций)",
    "открытые D# для продуктовых развилок (если найдены)"
  ],
  "route": {
    "class": "frontier",
    "effort": "medium"
  },
  "review": {
    "mode": "none"
  },
130→  "authority": {
    "kind": "routine"
  },
