import json
from collections import Counter
base='tests/Repo/Arch/Fixtures'
tm=json.load(open(base+'/target-map.json'))
typeOwners={t['fqcn']:t['owner'] for t in tm['types']}
fileOwners={}
for t in tm['types']:
    fileOwners.setdefault(t['file'], t['owner'])
for f in tm['files']:
    fileOwners.setdefault(f['file'], f['owner'])
memberOwners={m['fqcn']+'::'+m['member']:m['owner'] for m in tm['members']}

def owner_at(file, symbol):
    if symbol in memberOwners: return memberOwners[symbol]
    cls=symbol.split('::')[0].split('@anonymous')[0]
    return typeOwners.get(cls) or fileOwners.get(file)

i2=json.load(open(base+'/allowlists/i2.json'))['entries']
print('media->drive reverse files')
c=Counter()
for e in i2:
    if e['category']!='reverse-edge':
